# ---------- è¾…åŠ©å‡½æ•° ----------
prompt_continue() {
    if $AUTO_YES; then
        return 0
    fi
    local msg="${1:-æŒ‰å›žè½¦é”®ç»§ç»­ï¼Œæˆ–æŒ‰ Ctrl+C å–æ¶ˆ...}"
    read -p "$msg"
}

ask_yes_no() {
    if $AUTO_YES; then
        return 0
    fi
    local prompt="$1"
    read -p "${prompt} [Y/n] " answer
    [[ "$answer" =~ ^[Nn] ]] && return 1 || return 0
}

test_proxy() {
    local port=$1
    curl -x "http://127.0.0.1:${port}" -s --connect-timeout 5 --max-time 10 \
        "http://httpbin.org/ip" > /dev/null 2>&1
}

