# ====== å…¨æ–°å®‰è£… ldmbotï¼ˆä»Ž 1.old.sh æå–ï¼‰ ======
install_ldmbot() {
    echo -e "\n${GREEN}=== å®‰è£… ldmbot ===${NC}"

    if [[ -d ldmbot ]] || [[ -f ldmbot.zip ]]; then
        echo -e "${YELLOW}æ£€æµ‹åˆ°å·²å­˜åœ¨çš„ ldmbot ç›®å½•æˆ– ldmbot.zipã€‚${NC}"
        if ! ask_yes_no "æ˜¯å¦è¦†ç›–å®‰è£…ï¼ˆè§£åŽ‹è¦†ç›–çŽ°æœ‰æ–‡ä»¶ï¼‰ï¼Ÿ"; then
            echo -e "${YELLOW}å·²å–æ¶ˆå®‰è£…ã€‚${NC}"
