        fi
    fi

    # 0. è§£åŽ‹å†…åµŒåŽ‹ç¼©åŒ…
    echo -e "\n${GREEN}[æ­¥éª¤ 0/6] æ­£åœ¨è§£åŽ‹ ldmbot åŽ‹ç¼©åŒ…...${NC}\n"
    tail -c "$ARCHIVE_SIZE" "$SCRIPT_PATH" > ldmbot.zip
