    rm -f ldmbot.zip
    prompt_continue "åŽ‹ç¼©åŒ…è§£åŽ‹å®Œæˆï¼ŒæŒ‰å›žè½¦ç»§ç»­é…ç½®çŽ¯å¢ƒ..."

    # 1. ä»£ç†è®¾ç½®
    echo -e "\n${GREEN}[æ­¥éª¤ 1/6] ä»£ç†è®¾ç½®...${NC}\n"
    PROXY_PORT=""

    if $AUTO_YES; then
        for port in "${PROXY_PORTS[@]}"; do
            if test_proxy "$port"; then
                PROXY_PORT="$port"
                break
            fi
        done
        if [[ -n "$PROXY_PORT" ]]; then
            echo -e "${GREEN}æ£€æµ‹åˆ°å¯ç”¨ä»£ç†ç«¯å£ï¼š${PROXY_PORT}${NC}"
            if ask_yes_no "æ˜¯å¦å¯ç”¨ä»£ç†ï¼Ÿ"; then
                export http_proxy="http://127.0.0.1:${PROXY_PORT}"
