                export all_proxy="http://127.0.0.1:${PROXY_PORT}"
                echo -e "${GREEN}å·²å¯ç”¨ä»£ç†ã€‚${NC}\n"
            else
                echo -e "${YELLOW}å·²é€‰æ‹©ä¸å¯ç”¨ä»£ç†ã€‚${NC}\n"
            fi
        else
            echo -e "${YELLOW}è­¦å‘Šï¼šæœªæ£€æµ‹åˆ°å¯ç”¨ä»£ç†ï¼Œä¸‹è½½å¯èƒ½è¾ƒæ…¢ã€‚${NC}"
            prompt_continue "æŒ‰å›žè½¦ç»§ç»­..."
        fi
    else
        if ask_yes_no "æ˜¯å¦ä½¿ç”¨ä»£ç†ç«¯å£ï¼Ÿï¼ˆç”¨äºŽåŠ é€Ÿä¸‹è½½ï¼‰"; then
            while true; do
                read -p "è¯·è¾“å…¥ä»£ç†ç«¯å£å·ï¼ˆä¾‹å¦‚ 7890ï¼Œç›´æŽ¥å›žè½¦ä½¿ç”¨ 7890ï¼‰: " custom_port < /dev/tty
                custom_port=${custom_port:-7890}
                if [[ "$custom_port" =~ ^[0-9]+$ ]] && [ "$custom_port" -ge 1 ] && [ "$custom_port" -le 65535 ]; then
                    if test_proxy "$custom_port"; then
                        PROXY_PORT="$custom_port"
                        echo -e "${GREEN}ä»£ç†ç«¯å£ ${PROXY_PORT} è¿žæŽ¥æˆåŠŸã€‚${NC}"
                        break
                    else
                        echo -e "${RED}ç«¯å£ ${custom_port} ä¸å¯ç”¨ï¼Œè¯·æ£€æŸ¥ä»£ç†æ˜¯å¦å·²å¼€å¯ã€‚${NC}"
                        if ! ask_yes_no "æ˜¯å¦é‡æ–°è¾“å…¥ï¼Ÿ"; then
                            echo -e "${YELLOW}è·³è¿‡ä»£ç†è®¾ç½®ã€‚${NC}"
                            PROXY_PORT=""
                            break
                        fi
                    fi
                else
                    echo -e "${RED}æ— æ•ˆç«¯å£å·ã€‚${NC}"
                    if ! ask_yes_no "æ˜¯å¦é‡æ–°è¾“å…¥ï¼Ÿ"; then
                        echo -e "${YELLOW}è·³è¿‡ä»£ç†è®¾ç½®ã€‚${NC}"
                        PROXY_PORT=""
                        break
                    fi
                fi
            done
            if [[ -n "$PROXY_PORT" ]]; then
                export http_proxy="http://127.0.0.1:${PROXY_PORT}"
                export https_proxy="http://127.0.0.1:${PROXY_PORT}"
                export all_proxy="http://127.0.0.1:${PROXY_PORT}"
                echo -e "${GREEN}å·²å¯ç”¨ä»£ç†ã€‚${NC}\n"
            fi
        else
            echo -e "${YELLOW}å·²é€‰æ‹©ä¸ä½¿ç”¨ä»£ç†ã€‚${NC}\n"
        fi
    fi

    # 2. uv æ£€æŸ¥
    echo -e "\n${GREEN}[æ­¥éª¤ 2/6] æ£€æŸ¥ uv åŒ…ç®¡ç†å™¨...${NC}\n"
    USE_UV=false
    if command -v uv &>/dev/null; then
        USE_UV=true
        echo -e "${GREEN}å·²æ‰¾åˆ° uvï¼š$(which uv)${NC}\n"
    else
        echo -e "${YELLOW}æœªæ‰¾åˆ° uvã€‚${NC}"
        prompt_continue "æŒ‰å›žè½¦è‡ªåŠ¨å®‰è£… uv..."
        if curl -LsSf https://astral.sh/uv/install.sh | sh; then
            export PATH="$HOME/.local/bin:$PATH"
            command -v uv &>/dev/null && USE_UV=true && echo -e "${GREEN}uv å®‰è£…æˆåŠŸã€‚${NC}\n" || echo -e "${YELLOW}uv ä¸åœ¨ PATH ä¸­ã€‚${NC}\n"
        else
            echo -e "${YELLOW}uv å®‰è£…å¤±è´¥ã€‚${NC}\n"
        fi
    fi

    # è¿›å…¥é¡¹ç›®ç›®å½•
    cd ldmbot || { echo -e "${RED}è§£åŽ‹åŽæœªæ‰¾åˆ° ldmbot ç›®å½•ã€‚${NC}"; exit 1; }

    # 3. uv sync è¯¢é—®ä¸Žæ‰§è¡Œ
    if $USE_UV; then
        if $SKIP_SYNC; then
            echo -e "\n${YELLOW}å·²é€šè¿‡ --no-sync è·³è¿‡ uv syncã€‚ç›´æŽ¥å°è¯•å¯åŠ¨...${NC}\n"
            exec uv run main.py
        fi

        if ! $AUTO_YES; then
            if ask_yes_no "æ˜¯å¦è¿è¡Œ uv sync å®‰è£…/æ›´æ–°ä¾èµ–ï¼Ÿ"; then
                INSTALL_DEPS=true
            else
                INSTALL_DEPS=false
                echo -e "${YELLOW}è·³è¿‡ uv syncã€‚ç›´æŽ¥å°è¯•å¯åŠ¨...${NC}"
            fi
        else
            INSTALL_DEPS=true
        fi

        if $INSTALL_DEPS; then
            echo -e "\n${GREEN}[æ­¥éª¤ 3/6] uv sync å¹¶å¯åŠ¨...${NC}\n"
            if uv sync; then
                echo -e "${GREEN}é€šè¿‡ uv å¯åŠ¨...${NC}\n"
                exec uv run main.py
            fi
            echo -e "${YELLOW}uv sync å¤±è´¥ï¼Œå›žé€€åˆ° pipã€‚${NC}"
            prompt_continue "æŒ‰å›žè½¦ç»§ç»­..."
        else
            exec uv run main.py
        fi
    fi

    # 4. å›žé€€ï¼špip + Python â‰¥ 3.12
    echo -e "\n${GREEN}[æ­¥éª¤ 4/6] å‡†å¤‡ pip çŽ¯å¢ƒ...${NC}\n"

    if ! $USE_UV && ! $AUTO_YES && $INSTALL_DEPS; then
