def _å…¨å±€éåŽ†æ”¶é›†(
    åŒ¹é…: Callable[[str, list[str]], list[Path]],
    è¿›åº¦æç¤º: str,
) -> list[Path]:
    """ä»Žå¸¸è§æ ¹ç›®å½• os.walk æœç´¢ï¼Œå¿½ç•¥æƒé™é”™è¯¯ã€‚"""
    print(f"\nâ³ {è¿›åº¦æç¤º}")
    print("   ï¼ˆå¯èƒ½éœ€è¦è¾ƒé•¿æ—¶é—´ï¼ŒæŒ‰ Ctrl+C å¯ä¸­æ–­ï¼‰")
    roots: list[Path] = []
    for r in (Path("/"), Path.home()):
        if r.exists() and r not in roots:
            roots.append(r)
    # WSL å¸¸è§ Windows æŒ‚è½½
    mnt = Path("/mnt")
    if mnt.is_dir():
        for child in sorted(mnt.iterdir()):
            if child.is_dir() and child.name.isalpha() and len(child.name) == 1:
                roots.append(child)

    found: list[Path] = []
    seen: Set[str] = set()
    try:
        for root in roots:
            print(f"   â€¦ æ‰«æ {root}")
            for dirpath, dirnames, filenames in os.walk(root, onerror=lambda _e: None):
                # åŽŸåœ°è£å‰ªï¼Œé¿å…è¿›å…¥æ— æ„ä¹‰/é«˜æƒé™ç›®å½•
                dirnames[:] = [
                    d for d in dirnames
                    if d not in _è·³è¿‡ç›®å½•å and not d.startswith(".")
                ]
                try:
                    hits = åŒ¹é…(dirpath, filenames)
                except (PermissionError, OSError):
                    continue
                for p in hits:
                    key = str(p.resolve()) if p.exists() else str(p)
                    if key not in seen:
                        seen.add(key)
                        found.append(p)
    except KeyboardInterrupt:
        print("\nâš ï¸ å…¨å±€æœç´¢å·²è¢«ä¸­æ–­ï¼Œå°†ä½¿ç”¨ç›®å‰å·²æ‰¾åˆ°çš„ç»“æžœã€‚")
    print(f"   å…±æ‰¾åˆ° {len(found)} ä¸ªå€™é€‰ã€‚")
    return found


def æ ¡éªŒNapCaté…ç½®æ–‡ä»¶(path: Path) -> Optional[str]:
    """æ ¡éªŒæ˜¯å¦åƒå¯ç”¨çš„ NapCat onebot é…ç½®ï¼›é€šè¿‡è¿”å›ž Noneã€‚"""
    name = path.name
    if not name.endswith(".json"):
        return "æ–‡ä»¶æ‰©å±•ååº”ä¸º .json"
    if name.endswith("_.json"):
        return "è¿™æ˜¯æ¨¡æ¿æ–‡ä»¶ï¼ˆ*_ .jsonï¼‰ï¼Œè¯·é€‰æ‹©å¸¦ QQ å·çš„æ­£å¼é…ç½®"
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception as e:
        return f"æ— æ³•è§£æž JSONï¼š{e}"
    if not isinstance(data, dict):
        return "é…ç½®æ ¹èŠ‚ç‚¹åº”ä¸º JSON å¯¹è±¡"
    return None


