def å…¨å±€æœç´¢NapCaté…ç½®æ–‡ä»¶() -> list[Path]:
    """å…¨ç›˜æœç´¢ NapCat onebot é…ç½®ã€‚"""

    def åŒ¹é…(dirpath: str, filenames: list[str]) -> list[Path]:
        base = Path(dirpath)
        # è·¯å¾„å½¢å¦‚ .../napcat/config/
        if base.name != "config":
