# ---------- å·¥å…·ï¼šä»Žé…ç½®ä¸­æå–å·²ç”¨ç«¯å£ ----------
def extract_ports(config: Any, used_ports: Set[int] = None) -> Set[int]:
    """é€’å½’éåŽ†é…ç½®å¯¹è±¡ï¼Œæ”¶é›†æ‰€æœ‰ç«¯å£å·"""
    if used_ports is None:
        used_ports = set()
    if isinstance(config, dict):
        for key, value in config.items():
            if key == "port" and isinstance(value, int):
                used_ports.add(value)
            elif key == "url" and isinstance(value, str):
                port = _extract_port_from_url(value)
                if port is not None:
                    used_ports.add(port)
            else:
                extract_ports(value, used_ports)
    elif isinstance(config, list):
        for item in config:
            extract_ports(item, used_ports)
    return used_ports


def _extract_port_from_url(url: str) -> Optional[int]:
    """ä»Ž URL ä¸­è§£æžç«¯å£å·"""
    try:
        parsed = urlparse(url)
        if parsed.port is not None:
            return parsed.port
    except Exception:
        pass
    return None


# ---------- å·¥å…·ï¼šä»Žé…ç½®ä¸­æå–å·²ç”¨åç§° ----------
def extract_names(config, names_set=None):
    """é€’å½’æå–æ‰€æœ‰ "name" é”®çš„å€¼"""
    if names_set is None:
        names_set = set()
    if isinstance(config, dict):
        for key, value in config.items():
            if key == "name" and isinstance(value, str):
                names_set.add(value)
            else:
                extract_names(value, names_set)
    elif isinstance(config, list):
        for item in config:
            extract_names(item, names_set)
    return names_set


# ---------- ç«¯å£å ç”¨æ£€æµ‹ ----------
def is_port_in_use(port: int, host: str = "127.0.0.1") -> bool:
    """æ£€æµ‹æœ¬æœºç«¯å£æ˜¯å¦è¢«å ç”¨"""
    if not (1 <= port <= 65535):
        raise ValueError("ç«¯å£å·å¿…é¡»åœ¨ 1~65535 ä¹‹é—´")
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
        try:
            sock.bind((host, port))
            return False
        except OSError:
            return True


# ---------- NapCat é…ç½®å†™å…¥ ----------
def å†™å…¥NapCatåå‘WSé…ç½®(path: Path, port: int, client_name: str):
    """åœ¨ NapCat çš„ onebot é…ç½®ä¸­æ·»åŠ ä¸€æ¡åå‘ websocket å®¢æˆ·ç«¯"""
    with open(path, "r", encoding="utf-8") as f:
        cfg = json.load(f)

    # ç¡®ä¿ network å’Œ websocketClients å­˜åœ¨
    if "network" not in cfg or not isinstance(cfg.get("network"), dict):
        cfg["network"] = {}
    if "websocketClients" not in cfg["network"] or not isinstance(cfg["network"]["websocketClients"], list):
        cfg["network"]["websocketClients"] = []

    # ç”Ÿæˆä¸é‡å¤çš„ name
    existing_names = extract_names(cfg["network"]["websocketClients"])
    final_name = client_name
    counter = 1
    while final_name in existing_names:
        final_name = f"{client_name}_{counter}"
        counter += 1

    new_client = {
        "enable": True,
        "name": final_name,
        "url": f"ws://127.0.0.1:{port}/ws",
        "reportSelfMessage": False,
        "messagePostFormat": "array",
        "token": "",
        "debug": False,
        "heartInterval": 5000,
        "reconnectInterval": 5000,
        "verifyCertificate": False
    }
    cfg["network"]["websocketClients"].append(new_client)

    with open(path, "w", encoding="utf-8") as f:
        json.dump(cfg, f, ensure_ascii=False, indent=4)
    print(f"âœ… å·²å‘ NapCat é…ç½®æ·»åŠ åå‘ WS å®¢æˆ·ç«¯ï¼šname={final_name}, port={port}")
    return final_name


# ---------- ldmbot é…ç½®ç›¸å…³ ----------
def find_ldmbot_config_dirs(home: Path) -> list[Path]:
    """æœç´¢ home ä¸‹æ‰€æœ‰åŒ…å« ANCHOR çš„è·¯å¾„ï¼Œè¿”å›žå¯¹åº”çš„é¡¹ç›®æ ¹ç›®å½•åˆ—è¡¨"""
    try:
        results = list(home.glob(f"**/{ANCHOR}/**"))
    except (PermissionError, OSError):
        results = []
    dynamic_dirs = set()
    for p in results:
        try:
            rel = p.relative_to(home)
        except ValueError:
            continue
        str_rel = rel.as_posix()
        before, _ = str_rel.split(ANCHOR, 1)
        before = before.rstrip("/")
        first_dir = home / before if before else home
        dynamic_dirs.add(first_dir)
    return sorted(dynamic_dirs)


def å…¨å±€æœç´¢ldmboté…ç½®æ–‡ä»¶() -> list[Path]:
    """å…¨ç›˜æœç´¢ ldmbot çš„ data/cmd_config.jsonï¼ˆè¦æ±‚åŒæ ‘å†…å­˜åœ¨ ANCHORï¼‰ã€‚"""
    anchor_parts = ANCHOR.split("/")

    def åŒ¹é…(dirpath: str, filenames: list[str]) -> list[Path]:
        if "cmd_config.json" not in filenames:
            return []
        base = Path(dirpath)
        if base.name != "data":
            return []
        # é¡¹ç›®æ ¹ = data çš„çˆ¶ç›®å½•ï¼›è¦æ±‚å…¶ä¸‹å­˜åœ¨ ANCHOR
        project_root = base.parent
        if not (project_root.joinpath(*anchor_parts)).exists():
            return []
        return [base / "cmd_config.json"]

    return _å…¨å±€éåŽ†æ”¶é›†(åŒ¹é…, "æ­£åœ¨å…¨å±€æœç´¢ ldmbot é…ç½® (cmd_config.json)â€¦")


def get_ldmbot_config_paths(base_dirs: list[Path]) -> list[Path]:
    """è¿”å›žæ‰€æœ‰å¯èƒ½å­˜åœ¨çš„ ldmbot é…ç½®æ–‡ä»¶è·¯å¾„"""
    return [d / CONFIG_REL for d in base_dirs]


def filter_existing(paths: list[Path]) -> tuple[list[Path], list[Path]]:
    """åˆ†ç¦»å­˜åœ¨ä¸Žä¸å­˜åœ¨çš„é…ç½®æ–‡ä»¶è·¯å¾„"""
    valid, invalid = [], []
    for p in paths:
        (valid if p.exists() else invalid).append(p)
    return valid, invalid


