def load_json(path: Path) -> dict:
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def save_json(path: Path, data: dict) -> None:
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=4)


def å‘ldmbotæ·»åŠ NapCatå¹³å°(config: dict, port: int, platform_id: str):
    """åœ¨ ldmbot çš„ cmd_config.json ä¸­æ·»åŠ  aiocqhttp å¹³å°é…ç½®"""
    if "platform" not in config or not isinstance(config.get("platform"), list):
        config["platform"] = []

    platforms = config["platform"]

    # ç”Ÿæˆä¸é‡å¤çš„ id
    existing_ids = set()
    for item in platforms:
        if isinstance(item, dict) and "id" in item:
            existing_ids.add(item["id"])

    final_id = platform_id
    counter = 1
    while final_id in existing_ids:
        final_id = f"{platform_id}_{counter}"
        counter += 1

    platforms.append({
        "id": final_id,
        "type": "aiocqhttp",
        "enable": True,
        "ws_reverse_host": "127.0.0.1",
        "ws_reverse_port": port,
        "ws_reverse_token": ""
    })
    return final_id


