                    search_results=$( { find ~/ -type d -path "*astrbot/builtin_stars/astrbot/ldm" 2>/dev/null || true; } | sed 's|/astrbot/builtin_stars/astrbot/ldm$||' | sort -u )
                    if [[ -z "$search_results" ]]; then
                        echo -e "${RED}æœªæ‰¾åˆ°åŒ…å« astrbot/builtin_stars/astrbot/ldm çš„ç›®å½•ã€‚${NC}"
                        continue
                    fi
                    readarray -t candidates <<< "$search_results"
                    if [[ ${#candidates[@]} -eq 1 ]]; then
                        target_path="${candidates[0]}"
                        echo -e "${GREEN}è‡ªåŠ¨é€‰æ‹©å”¯ä¸€ç›®å½•ï¼š${target_path}${NC}"
                    else
                        echo "æ‰¾åˆ°ä»¥ä¸‹å¯èƒ½çš„ ldmbot æ ¹ç›®å½•ï¼š"
                        i=1
                        for dir in "${candidates[@]}"; do
                            echo "$i) $dir"
                            ((i++))
                        done
                        while true; do
                            read -p "è¯·é€‰æ‹©åºå·ï¼ˆæˆ–è¾“å…¥ 0 é€€å‡ºï¼‰: " choice_idx < /dev/tty
                            if [[ "$choice_idx" == "0" ]]; then
                                echo -e "${YELLOW}å·²å–æ¶ˆã€‚${NC}"
                                exit 0
                            elif [[ "$choice_idx" =~ ^[0-9]+$ ]] && (( choice_idx >= 1 && choice_idx <= ${#candidates[@]} )); then
                                target_path="${candidates[$((choice_idx-1))]}"
                                break
                            else
                                echo -e "${RED}æ— æ•ˆé€‰æ‹©ã€‚${NC}"
                            fi
                        done
                    fi
                    break
                elif [[ -d "$target_path" ]]; then
                    # æ£€æŸ¥æ˜¯å¦åŒ…å«å¯å¯åŠ¨æ–‡ä»¶
                    if [[ -f "$target_path/main.py" ]] || [[ -d "$target_path/ldmbot" ]]; then
                        break
                    else
                        echo -e "${RED}ç›®å½• $target_path ä¸­æœªæ‰¾åˆ° main.py æˆ– ldmbot å­ç›®å½•ï¼Œè¯·é‡æ–°è¾“å…¥ã€‚${NC}"
                    fi
                else
                    echo -e "${RED}ç›®å½• $target_path ä¸å­˜åœ¨ã€‚${NC}"
                fi
            done

            # è¿›å…¥ç›®æ ‡ç›®å½•å¹¶å¯åŠ¨
            cd "$target_path" || { echo -e "${RED}æ— æ³•è¿›å…¥ç›®å½•ã€‚${NC}"; exit 1; }
            # å¦‚æžœå­˜åœ¨ ldmbot å­ç›®å½•åˆ™è¿›å…¥
            if [[ -d ldmbot ]]; then
                cd ldmbot || exit 1
            fi
            # å¯åŠ¨é€»è¾‘ï¼ˆå¤ç”¨ try_direct_run çš„åŽåŠéƒ¨åˆ†ï¼‰
            if command -v uv &>/dev/null && [[ -f pyproject.toml ]]; then
                echo -e "${GREEN}ä½¿ç”¨ uv å¯åŠ¨...${NC}"
                exec uv run main.py
            elif [[ -d .venv ]]; then
                echo -e "${GREEN}ä½¿ç”¨è™šæ‹ŸçŽ¯å¢ƒä¸­çš„ python å¯åŠ¨...${NC}"
                source .venv/bin/activate
                exec python main.py
            elif command -v python3 &>/dev/null; then
                echo -e "${YELLOW}å°è¯•ç›´æŽ¥ä½¿ç”¨ç³»ç»Ÿ python3 å¯åŠ¨...${NC}"
                exec python3 main.py
            else
                echo -e "${RED}æ— æ³•æ‰¾åˆ°å¯ç”¨çš„å¯åŠ¨æ–¹å¼ï¼Œè¯·æ£€æŸ¥ç›®å½•å†…å®¹ã€‚${NC}"
                exit 1
            fi
        fi
        ;;
    3)
        update_ldmbot true   # äº¤äº’å¼æ›´æ–°
        ;;
    4)
        echo -e "${RED}å·²é€€å‡ºã€‚${NC}"
        exit 0
        ;;
    5)
        migrate_official
        exit 0
        ;;
    6)
        install_napcat   # å®‰è£… NapCat
        ;;
    7)
        configure_napcat_connection
        ;;
    *)
        echo -e "${RED}æ— æ•ˆé€‰é¡¹ï¼Œå·²é€€å‡ºã€‚${NC}"
